text:
getDefaults() {
  const states = Object.assign({}, this._defaultStates);
  return {
    text: null,
    states,
  };
},
propagateState(aOld, aSticky) {
  return {
    text: aSticky ? aOld.text : null,
    states: Object.assign({}, aOld.states),
  };
},
clearState(aState) {
  const hadState = Boolean(aState.text);
  aState.text = null;
  return [aState, hadState];
},
